<div id="wrapper"><div class="content sccc-app"><div class="sccc-page-head"><div><h3><?= _l('sccc_callbacks') ?></h3><p class="text-muted"><?= _l('sccc_callbacks_subtitle') ?></p></div></div><?php $rows=$this->db->order_by('id','DESC')->get(db_prefix().'sccc_callbacks')->result_array();?><div class="sccc-card"><table class="table"><thead><tr><th>#</th><th><?= _l('sccc_name')?></th><th><?= _l('sccc_phone')?></th><th><?= _l('sccc_due')?></th><th><?= _l('sccc_status')?></th></tr></thead><tbody><?php foreach($rows as $r){?><tr><td><?= $r['id']?></td><td><?= html_escape($r['name'])?></td><td><?= html_escape(sccc_phone_display($r['phone']))?></td><td><?= html_escape($r['due_at'])?></td><td><?= html_escape($r['status'])?></td></tr><?php }?></tbody></table></div></div></div><?php init_tail(); ?>